import{_ as a,o as i,c as t,a3 as o}from"./chunks/framework.WFmvnizL.js";const u=JSON.parse('{"title":"Dashboard Configuration","description":"Complete Nezha Monitoring V2 Dashboard YAML configuration reference for domains, TLS, real IP, OAuth2, JWT, frontends, MCP, TSDB, memory, and notification privacy.","frontmatter":{"description":"Complete Nezha Monitoring V2 Dashboard YAML configuration reference for domains, TLS, real IP, OAuth2, JWT, frontends, MCP, TSDB, memory, and notification privacy.","outline":"deep"},"headers":[],"relativePath":"en_US/configuration/dashboard.md","filePath":"en_US/configuration/dashboard.md","lastUpdated":1792850916000}'),l={name:"en_US/configuration/dashboard.md"};function n(s,e,d,r,c,h){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="dashboard-configuration" tabindex="-1">Dashboard Configuration <a class="header-anchor" href="#dashboard-configuration" aria-label="Permalink to &quot;Dashboard Configuration&quot;">​</a></h1><p>Dashboard configuration is in YAML format, where items marked with * can only be modified through the configuration file, while other configuration items should use the admin frontend when it exposes them. See <a href="/en_US/guide/settings.html">Settings</a> for details.</p><hr><h2 id="files-defaults-and-editing" tabindex="-1">Files, defaults, and editing <a class="header-anchor" href="#files-defaults-and-editing" aria-label="Permalink to &quot;Files, defaults, and editing&quot;">​</a></h2><p>Dashboard defaults to <code>data/config.yaml</code> relative to its working directory; <code>-c</code> selects another file and <code>-db</code> independently selects the SQLite database. See <a href="/en_US/configuration/environment.html">loading and environment variables</a> before mixing sources. Missing/zero values use the defaults below where implemented; empty strings and maps are shown explicitly. For complete scenarios, see <a href="/en_US/configuration/examples.html">configuration recipes</a>.</p><p>File-only settings require restart. Admin-supported settings can be saved through the UI, but availability in the settings API does not guarantee a visible UI control. In particular, <code>admin_template</code> is not in <code>SettingForm</code> and must be edited in the file.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><ul><li><h5 id="language" tabindex="-1"><strong><code>language</code></strong> <a class="header-anchor" href="#language" aria-label="Permalink to &quot;**`language`**&quot;">​</a></h5><ul><li><p>Type: <code>string</code>; default: <code>en_US</code>.</p></li><li><p>Language setting for Dashboard.</p></li><li><p>Requires filling in POSIX-style locale codes, such as <code>en_US</code>. For a list of supported languages, see <a href="https://hosted.weblate.org/projects/nezha/nezha-dashboard" target="_blank" rel="noreferrer">https://hosted.weblate.org/projects/nezha/nezha-dashboard</a>.</p></li><li><p>YAML uses underscore locale codes, such as <code>zh_CN</code> and <code>en_US</code>. The frontend may display hyphenated tags such as <code>zh-CN</code> and <code>en-US</code>, which are converted back to the YAML format when saved.</p></li></ul></li><li><h5 id="site-name" tabindex="-1"><strong><code>site_name</code></strong> <a class="header-anchor" href="#site-name" aria-label="Permalink to &quot;**`site_name`**&quot;">​</a></h5><ul><li><p>Type: <code>string</code>; default: <code>&quot;&quot;</code>.</p></li><li><p>Site name, such as <code>Nezha</code>.</p></li></ul></li><li><h5 id="custom-code" tabindex="-1"><strong><code>custom_code</code></strong> <a class="header-anchor" href="#custom-code" aria-label="Permalink to &quot;**`custom_code`**&quot;">​</a></h5><ul><li><p>Type: <code>string</code>; default: <code>&quot;&quot;</code>.</p></li><li><p>Custom code for the user frontend, injected into the public user frontend.</p></li><li><p>User frontend variables such as <code>window.ForceShowServices</code>, <code>window.ForceShowMap</code>, and <code>window.ForceCardInline</code> only take effect here.</p></li></ul></li><li><h5 id="custom-code-dashboard" tabindex="-1"><strong><code>custom_code_dashboard</code></strong> <a class="header-anchor" href="#custom-code-dashboard" aria-label="Permalink to &quot;**`custom_code_dashboard`**&quot;">​</a></h5><ul><li><p>Type: <code>string</code>; default: <code>&quot;&quot;</code>.</p></li><li><p>Custom code for the admin frontend, used by admin frontend pages, including their login flow; not secret storage.</p></li></ul></li><li><h5 id="install-host" tabindex="-1"><strong><code>install_host</code></strong> <a class="header-anchor" href="#install-host" aria-label="Permalink to &quot;**`install_host`**&quot;">​</a></h5><ul><li><p>Type: <code>string</code>; default: <code>&quot;&quot;</code>.</p></li><li><p>Specifies the server address for the installation command, in the format <code>host:port</code>.</p></li><li><p>The frontend uses this value to generate Agent installation commands. Dashboard also treats its Host as a trusted OAuth2 callback Host and a reserved NAT hostname.</p></li></ul></li><li><h5 id="dashboard-host" tabindex="-1"><strong><code>dashboard_host</code></strong> <a class="header-anchor" href="#dashboard-host" aria-label="Permalink to &quot;**`dashboard_host`**&quot;">​</a></h5><ul><li><p>Type: <code>string</code>; default: <code>&quot;&quot;</code>.</p></li><li><p>Specifies the public Dashboard address used for OAuth2 callbacks, in the format <code>domain/IP[:port]</code>. Do not include a scheme or path; omit the port when using the default HTTP/HTTPS port.</p></li><li><p>Set this explicitly when Dashboard has a fixed public entry point, especially when its public address differs from <code>install_host</code>.</p></li><li><p>During an OAuth2 callback, if the request Host does not match <code>dashboard_host</code>, <code>install_host</code>, <code>listen_host</code>, or <code>reserved_hosts</code>, Dashboard replaces the callback Host with this value. When empty, Dashboard trusts the request Host.</p></li><li><p>This address is also reserved automatically for NAT, preventing normal members from creating a conflicting NAT rule.</p></li></ul></li><li><h5 id="reserved-hosts" tabindex="-1"><strong><code>reserved_hosts</code></strong> <a class="header-anchor" href="#reserved-hosts" aria-label="Permalink to &quot;**`reserved_hosts`**&quot;">​</a></h5><ul><li><p>Type: <code>string</code>; default: <code>&quot;&quot;</code>.</p></li><li><p>Comma-separated public Dashboard hostnames, for example <code>nezha.example.com,status.example.com</code>.</p></li><li><p>This prevents normal members from creating NAT domains that collide with Dashboard entry hosts and hijack the panel route in reverse-proxy deployments.</p></li><li><p>When Dashboard runs behind a reverse proxy and cannot reliably infer its public hostnames, explicitly list every public entry hostname here.</p></li><li><p>These hostnames are also trusted as OAuth2 callback Hosts. If you use multiple public entry points, register the corresponding callback URLs with the OAuth2 provider as well.</p></li></ul></li><li><h5 id="tls" tabindex="-1"><strong><code>tls</code></strong> <a class="header-anchor" href="#tls" aria-label="Permalink to &quot;**`tls`**&quot;">​</a></h5><ul><li><p>Type: <code>bool</code>; default: <code>false</code>.</p></li><li><p>Boolean value, specifies whether the installation command enables TLS.</p></li><li><p>Set this to <code>true</code> only when Agents connect through HTTPS, Dashboard built-in HTTPS, or a reverse proxy/CDN that terminates TLS. Do not enable it when <code>install_host</code> is a plaintext direct <code>host:port</code>.</p></li><li><p>The actual effect of this option is implemented by the frontend, and Dashboard itself does not use it.</p></li></ul></li><li><h5 id="debug" tabindex="-1"><strong><code>debug</code></strong> * <a class="header-anchor" href="#debug" aria-label="Permalink to &quot;**`debug`** \\*&quot;">​</a></h5><ul><li><p>Type: <code>bool</code>; default: <code>false</code>.</p></li><li><p>Boolean value, whether to turn on debug mode.</p></li><li><p>When enabled, additional database logs and error logs when some functions do not work properly will be displayed.</p></li><li><p>At the same time, WebSocket same-origin policy will allow connections from loopback addresses.</p></li></ul></li><li><h5 id="web-real-ip-header" tabindex="-1"><strong><code>web_real_ip_header</code></strong> <a class="header-anchor" href="#web-real-ip-header" aria-label="Permalink to &quot;**`web_real_ip_header`**&quot;">​</a></h5><ul><li><p>Type: <code>string</code>; default: <code>&quot;&quot;</code>.</p></li><li><p>Specifies visitor&#39;s real IP request header for the Dashboard, such as <code>X-Real-Ip</code>.</p></li><li><p>After filling in, the built-in WAF will be automatically enabled, see <a href="/en_US/guide/settings.html#web-application-firewall">Web Application Firewall</a>.</p></li><li><p>If the option value is <code>NZ::Use-Peer-IP</code>, WAF will directly use the connection IP, and no longer need the upper-layer application to pass the request header.</p></li><li><p>For complete usage instructions, reverse proxy examples, and recovery steps, see <a href="/en_US/guide/q12.html">Frontend Real IP Header Configuration</a>.</p></li></ul></li><li><h5 id="agent-real-ip-header" tabindex="-1"><strong><code>agent_real_ip_header</code></strong> <a class="header-anchor" href="#agent-real-ip-header" aria-label="Permalink to &quot;**`agent_real_ip_header`**&quot;">​</a></h5><ul><li><p>Type: <code>string</code>; default: <code>&quot;&quot;</code>.</p></li><li><p>Specifies Agent&#39;s real IP request header for the Dashboard, such as <code>X-Real-Ip</code>.</p></li><li><p>If the option value is <code>NZ::Use-Peer-IP</code>, Dashboard will directly use the connection IP, and no longer need the upper-layer application to pass the request header.</p></li></ul></li><li><h5 id="enable-mcp" tabindex="-1"><strong><code>enable_mcp</code></strong> <a class="header-anchor" href="#enable-mcp" aria-label="Permalink to &quot;**`enable_mcp`**&quot;">​</a></h5><ul><li><p>Type: <code>bool</code>; default: <code>false</code>.</p></li><li><p>Boolean value, whether to enable the Dashboard&#39;s built-in MCP (Model Context Protocol) HTTP endpoint.</p></li><li><p>Disabled by default. When enabled, clients can call MCP tools through <code>POST /mcp</code> with an API Token; this endpoint does not accept JWT.</p></li><li><p>When switching from enabled to disabled, the Dashboard fires a kill switch that removes MCP file-transfer temporary URLs, revokes MCP transfer streams, and cancels in-flight MCP RPC calls.</p></li><li><p>For API Token scopes and usage, see <a href="/en_US/guide/api.html#api-token-pat">API Interface</a>.</p></li></ul></li><li><h5 id="user-template" tabindex="-1"><strong><code>user_template</code></strong> <a class="header-anchor" href="#user-template" aria-label="Permalink to &quot;**`user_template`**&quot;">​</a></h5><ul><li><p>Type: <code>string</code>; default: <code>user-dist</code>.</p></li><li><p>Default theme used by the user frontend.</p></li><li><p>Only filling in the built-in theme path is supported, see <a href="https://github.com/nezhahq/nezha/blob/master/service/singleton/frontend-templates.yaml" target="_blank" rel="noreferrer">service/singleton/frontend-templates.yaml</a>.</p></li></ul></li><li><h5 id="admin-template" tabindex="-1"><strong><code>admin_template</code></strong> * <a class="header-anchor" href="#admin-template" aria-label="Permalink to &quot;**`admin_template`** \\*&quot;">​</a></h5><ul><li><p>Type: <code>string</code>; default: <code>admin-dist</code>.</p></li><li><p>Default theme used by the admin frontend.</p></li><li><p>Only filling in the built-in theme path is supported, see <a href="https://github.com/nezhahq/nezha/blob/master/service/singleton/frontend-templates.yaml" target="_blank" rel="noreferrer">service/singleton/frontend-templates.yaml</a>.</p></li></ul></li><li><h5 id="location" tabindex="-1"><strong><code>location</code></strong> * <a class="header-anchor" href="#location" aria-label="Permalink to &quot;**`location`** \\*&quot;">​</a></h5><ul><li><p>Type: <code>string</code>; default: <code>Asia/Shanghai</code>.</p></li><li><p>Time zone used by the program, mainly affecting notifications and database queries.</p></li><li><p>Defaults to <code>Asia/Shanghai</code>.</p></li></ul></li><li><h5 id="force-auth" tabindex="-1"><strong><code>force_auth</code></strong> * <a class="header-anchor" href="#force-auth" aria-label="Permalink to &quot;**`force_auth`** \\*&quot;">​</a></h5><ul><li><p>Type: <code>bool</code>; default: <code>false</code>.</p></li><li><p>Boolean value, whether to enable &quot;force authentication&quot;.</p></li><li><p>After enabling, you need to log in to view server and service monitoring related data.</p></li></ul></li><li><h5 id="agent-secret-key" tabindex="-1"><strong><code>agent_secret_key</code></strong> * <a class="header-anchor" href="#agent-secret-key" aria-label="Permalink to &quot;**`agent_secret_key`** \\*&quot;">​</a></h5><ul><li><p>Type: <code>string</code>; default: Generated compatibility secret.</p></li><li><p>Connection secret key for the Agent.</p></li><li><p>This field is retained for legacy Agent compatibility. Current deployments should use user-bound connection secrets; see <a href="/en_US/guide/user.html#connection-secret">Connection Secret</a>.</p></li></ul></li><li><h5 id="jwt-timeout" tabindex="-1"><strong><code>jwt_timeout</code></strong> * <a class="header-anchor" href="#jwt-timeout" aria-label="Permalink to &quot;**`jwt_timeout`** \\*&quot;">​</a></h5><ul><li><p>Type: <code>integer</code>; default: <code>1</code>.</p></li><li><p>Integer, specifies the expiration time of JWT (hours).</p></li><li><p>The default value is <code>1</code>.</p></li></ul></li><li><h5 id="allow-jwt-ip-change" tabindex="-1"><strong><code>allow_jwt_ip_change</code></strong> <a class="header-anchor" href="#allow-jwt-ip-change" aria-label="Permalink to &quot;**`allow_jwt_ip_change`**&quot;">​</a></h5><ul><li><p>Type: <code>bool</code>; default: <code>false</code>.</p></li><li><p>Boolean, default <code>false</code>.</p></li><li><p>By default, browser login sessions are bound to the client&#39;s IP at login; an IP change requires signing in again. Set this to <code>true</code> to keep a JWT session usable after an IP change, for example when frequently switching networks. This relaxes session protection.</p></li><li><p>The current admin frontend has no switch for this option. Edit YAML and restart, or update <code>allow_jwt_ip_change</code> through the administrator settings API. PAT scopes, server allowlists, expiration, and revocation are unchanged.</p></li></ul></li><li><h5 id="jwt-secret-key" tabindex="-1"><strong><code>jwt_secret_key</code></strong> * <a class="header-anchor" href="#jwt-secret-key" aria-label="Permalink to &quot;**`jwt_secret_key`** \\*&quot;">​</a></h5><ul><li><p>Type: <code>string</code>; default: Generated if absent from file and environment.</p></li><li><p>JWT signing key. In production, inject it with the <code>NZ_JWTSECRETKEY</code> environment variable instead of writing it to the configuration file.</p></li><li><p>If neither the configuration file nor the environment variable provides a key, Dashboard generates one on first startup and writes it back to <code>config.yaml</code>.</p></li><li><p>When <code>NZ_JWTSECRETKEY</code> is set, Dashboard uses the environment value, does not write it to YAML, and skips version-driven automatic rotation. Operators should rotate it by updating the environment variable and restarting Dashboard.</p></li></ul></li><li><h5 id="jwt-secret-key-last-rotated-version" tabindex="-1"><strong><code>jwt_secret_key_last_rotated_version</code></strong> * <a class="header-anchor" href="#jwt-secret-key-last-rotated-version" aria-label="Permalink to &quot;**`jwt_secret_key_last_rotated_version`** \\*&quot;">​</a></h5><ul><li><p>Type: <code>string</code>; default: Automatically managed rotation metadata.</p></li><li><p>Records the Dashboard version that last completed JWT key rotation.</p></li><li><p>If <code>NZ_JWTSECRETKEY</code> is not used and the recorded rotation version is empty or below the current rotation baseline <code>v2.0.13</code>, Dashboard generates a new <code>jwt_secret_key</code> and updates this field.</p></li><li><p>Editing this field manually may invalidate sessions unnecessarily. Normally you only need to inspect it while troubleshooting upgrade rotation.</p></li></ul></li><li><h5 id="enable-plain-ip-in-notification" tabindex="-1"><strong><code>enable_plain_ip_in_notification</code></strong> <a class="header-anchor" href="#enable-plain-ip-in-notification" aria-label="Permalink to &quot;**`enable_plain_ip_in_notification`**&quot;">​</a></h5><ul><li><p>Type: <code>bool</code>; default: <code>false</code>.</p></li><li><p>Boolean value, whether the notification sends the original IP.</p></li><li><p>The default is <code>false</code>, that is, send the desensitized IP (such as 1.**.1).</p></li></ul></li><li><h5 id="enable-ip-change-notification" tabindex="-1"><strong><code>enable_ip_change_notification</code></strong> <a class="header-anchor" href="#enable-ip-change-notification" aria-label="Permalink to &quot;**`enable_ip_change_notification`**&quot;">​</a></h5><ul><li><p>Type: <code>bool</code>; default: <code>false</code>.</p></li><li><p>Boolean value, whether to enable IP change notification.</p></li></ul></li><li><h5 id="ip-change-notification-group-id" tabindex="-1"><strong><code>ip_change_notification_group_id</code></strong> <a class="header-anchor" href="#ip-change-notification-group-id" aria-label="Permalink to &quot;**`ip_change_notification_group_id`**&quot;">​</a></h5><ul><li><p>Type: <code>integer</code>; default: <code>0</code>.</p></li><li><p>Integer, specifies the notification group for IP change notification.</p></li></ul></li><li><h5 id="cover" tabindex="-1"><strong><code>cover</code></strong> <a class="header-anchor" href="#cover" aria-label="Permalink to &quot;**`cover`**&quot;">​</a></h5><ul><li><p>Type: <code>integer</code>; default: <code>1</code>.</p></li><li><p>Integer, specifies the coverage of IP change notification.</p></li><li><p><code>1</code> means full coverage, excluding the servers listed in <code>ignored_ip_notification</code>.</p></li><li><p><code>2</code> means ignore all, monitoring only the servers listed in <code>ignored_ip_notification</code>.</p></li></ul></li><li><h5 id="ignored-ip-notification" tabindex="-1"><strong><code>ignored_ip_notification</code></strong> <a class="header-anchor" href="#ignored-ip-notification" aria-label="Permalink to &quot;**`ignored_ip_notification`**&quot;">​</a></h5><ul><li><p>Type: <code>string</code>; default: <code>&quot;&quot;</code>.</p></li><li><p>Specifies the server ID for IP change notification, if the coverage is full coverage, then exclude these servers, if it is ignore all, then only monitor these servers.</p></li><li><p>Separated by commas, such as <code>1,2,3</code>.</p></li></ul></li><li><h5 id="avg-ping-count" tabindex="-1"><strong><code>avg_ping_count</code></strong> * <a class="header-anchor" href="#avg-ping-count" aria-label="Permalink to &quot;**`avg_ping_count`** \\*&quot;">​</a></h5><ul><li><p>Type: <code>integer</code>; default: <code>2</code>.</p></li><li><p>Integer, when the number of TCPing / ICMP Ping service data entries in memory reaches this value, the average value will be taken and written to the database.</p></li><li><p>The default is <code>2</code>, increasing this value can reduce the storage of the database.</p></li></ul></li><li><h5 id="online-stats-days" tabindex="-1"><strong><code>online_stats_days</code></strong> <a class="header-anchor" href="#online-stats-days" aria-label="Permalink to &quot;**`online_stats_days`**&quot;">​</a></h5><ul><li><p>Type: <code>integer</code>; default: <code>7</code>.</p></li><li><p>Integer, default <code>7</code>, valid range <code>7</code>–<code>3650</code> days.</p></li><li><p>Controls both online-session history retention and the online-history API&#39;s maximum query window. It does not control retention of CPU, network, or other TSDB metrics.</p></li><li><p>This field can be changed in the admin frontend system settings. The settings API rejects out-of-range values; at startup, a missing, <code>0</code>, or out-of-range YAML value falls back to <code>7</code>.</p></li><li><p>After reducing the range, closed sessions outside the window are periodically pruned. Increasing the range later cannot recover deleted history. See <a href="/en_US/guide/servers.html#online-history">Server online history</a>.</p></li></ul></li><li><h5 id="dns-servers" tabindex="-1"><strong><code>dns_servers</code></strong> <a class="header-anchor" href="#dns-servers" aria-label="Permalink to &quot;**`dns_servers`**&quot;">​</a></h5><ul><li><p>Type: <code>string</code>; default: <code>&quot;&quot;</code>.</p></li><li><p>List of DNS servers used by the DDNS module.</p></li><li><p>If not filled, the built-in list is used.</p></li></ul></li><li><h5 id="listen-port" tabindex="-1"><strong><code>listen_port</code></strong> * <a class="header-anchor" href="#listen-port" aria-label="Permalink to &quot;**`listen_port`** \\*&quot;">​</a></h5><ul><li><p>Type: <code>integer</code>; default: <code>8008</code>.</p></li><li><p>Dashboard listening port (HTTP).</p></li></ul></li><li><h5 id="listen-host" tabindex="-1"><strong><code>listen_host</code></strong> * <a class="header-anchor" href="#listen-host" aria-label="Permalink to &quot;**`listen_host`** \\*&quot;">​</a></h5><ul><li><p>Type: <code>string</code>; default: <code>&quot;&quot;</code>.</p></li><li><p>Dashboard bind address. Empty means wildcard binding; use <code>127.0.0.1</code> for loopback-only access. Container networking may require a different bind address.</p></li></ul></li><li><h5 id="oauth2" tabindex="-1"><strong><code>oauth2</code></strong> * <a class="header-anchor" href="#oauth2" aria-label="Permalink to &quot;**`oauth2`** \\*&quot;">​</a></h5><ul><li><p>Type: <code>map</code>; default: <code>{}</code>.</p></li><li><p>OAuth 2.0 related configuration, see <a href="/en_US/guide/q14.html">Setting OAuth 2.0 Binding</a>.</p></li></ul></li><li><h5 id="https" tabindex="-1"><strong><code>https</code></strong> * <a class="header-anchor" href="#https" aria-label="Permalink to &quot;**`https`** \\*&quot;">​</a></h5><ul><li>Type: <code>object</code>; default: <code>{}</code>.</li><li>HTTPS server configuration.</li><li>The following fields need to be filled in: <ul><li><code>listen_port</code>: Listening port</li><li><code>tls_cert_path</code>: TLS certificate path</li><li><code>tls_key_path</code>: TLS certificate private key path</li><li><code>insecure_tls</code>: Boolean, default <code>false</code>; a server-side setting, not a client trust switch</li></ul></li></ul></li><li><h5 id="tsdb" tabindex="-1"><strong><code>tsdb</code></strong> * <a class="header-anchor" href="#tsdb" aria-label="Permalink to &quot;**`tsdb`** \\*&quot;">​</a></h5><ul><li>Type: <code>object</code>; default: <code>{}</code>.</li><li>TSDB (Time Series Database) configuration, powered by VictoriaMetrics storage engine, used as an alternative to the default database for storing service monitoring history and server metrics.</li><li>Disabled by default. TSDB is enabled only after <code>tsdb.data_path</code> is configured and the Dashboard is restarted; leaving it empty keeps TSDB disabled.</li><li>Once enabled, the legacy <code>service_histories</code> database table will be automatically dropped. Historical data will NOT be migrated.</li><li>If <code>data_path</code> is not configured, TSDB will not be enabled and service monitoring history will continue to use database storage.</li><li>The following fields need to be filled in: <ul><li><code>data_path</code>: Data storage path, e.g. <code>data/tsdb</code>. Leave empty to disable TSDB</li><li><code>retention_days</code>: Data retention period in days, default <code>30</code></li><li><code>min_free_disk_space_gb</code>: Minimum free disk space (GB), stops writing when below this value, default <code>1</code></li><li><code>max_memory_mb</code>: Maximum memory usage (MB) for caching, default <code>256</code></li><li><code>write_buffer_size</code>: Write buffer size, batch writes when reaching this count, default <code>512</code></li><li><code>write_buffer_flush_interval</code>: Write buffer flush interval (seconds), default <code>5</code></li></ul></li><li>Example configuration:<div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tsdb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  data_path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/tsdb&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  retention_days</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  max_memory_mb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">256</span></span></code></pre></div></li><li>You can also set <code>tsdb.data_path</code> with the <code>NZ_TSDB_DATAPATH</code> environment variable. <code>TSDB initialized successfully</code> in the startup log means TSDB is enabled; <code>TSDB is disabled (tsdb.data_path not configured)</code> means it is still disabled.</li><li>For details, see <a href="/en_US/guide/q15.html">How to Enable TSDB</a>.</li></ul></li><li><h5 id="memory" tabindex="-1"><strong><code>memory</code></strong> * <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;**`memory`** \\*&quot;">​</a></h5><ul><li>Type: <code>object</code>; default: <code>{}</code>.</li><li>Memory configuration.</li><li>The following fields need to be filled in: <ul><li><code>go_mem_limit_mb</code>: Go runtime soft memory limit (MB); <code>0</code> sets no additional limit, not an RSS/container hard cap</li></ul></li></ul></li></ul><hr><h2 id="apply-config" tabindex="-1">Apply Config <a class="header-anchor" href="#apply-config" aria-label="Permalink to &quot;Apply Config&quot;">​</a></h2><p>After modifying the configuration file, you need to manually restart the Dashboard to apply the changes. The restart methods for different installation methods are different, as follows:</p><h3 id="docker-installation" tabindex="-1">Docker Installation <a class="header-anchor" href="#docker-installation" aria-label="Permalink to &quot;Docker Installation&quot;">​</a></h3><p>You can directly restart the Docker container:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nezha-dashboard</span></span></code></pre></div><p>Or recreate the container:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/nezha/dashboard</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><h3 id="standalone-installation" tabindex="-1">Standalone Installation <a class="header-anchor" href="#standalone-installation" aria-label="Permalink to &quot;Standalone Installation&quot;">​</a></h3><p>Taking <code>systemd</code> as an example:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nezha-dashboard.service</span></span></code></pre></div><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Operational details&quot;">​</a></h2><p><code>https.listen_port</code> defaults to <code>0</code> (disabled). Enabling it adds a listener without closing HTTP. Certificate/key paths default to empty; provide readable paths. <code>https.insecure_tls</code> defaults to <code>false</code> and does not configure client trust.</p><p><code>memory.go_mem_limit_mb</code> defaults to <code>0</code>: no additional runtime memory limit is set. A positive value is a Go soft limit, not an RSS or container hard cap.</p><p><code>dns_servers</code> is a comma-separated string for Dashboard DDNS, unlike the Agent <code>dns</code> array. OAuth2 is a provider-name map containing <code>client_id</code>, <code>client_secret</code>, <code>scopes</code>, and, for custom providers, <code>endpoint.auth_url</code>, <code>endpoint.token_url</code>, <code>user_info_url</code>, and <code>user_id_path</code>. See <a href="/en_US/guide/q14.html">OAuth2 configuration</a>.</p><p>Selected templates are validated against the bundled manifest. Local file overrides for the selected directory are described in <a href="/en_US/developer/theme-development.html">theme development</a>.</p><h2 id="related-documentation" tabindex="-1">Related documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related documentation&quot;">​</a></h2><ul><li><a href="/en_US/guide/architecture.html">Architecture and data flow</a></li><li><a href="/en_US/guide/security.html">Security and privacy</a></li><li><a href="/en_US/guide/version-compatibility.html">Version and compatibility</a></li><li><a href="/en_US/guide/dashboardq.html">Dashboard troubleshooting</a></li></ul>',26)])])}const g=a(l,[["render",n]]);export{u as __pageData,g as default};
